        var ang = jzLerp(-70, -20, jzR(d.seed, k, 1)) * Math.PI / 180, cx = jzLerp(W * 0.3, W * 0.7, jzR(d.seed, k, 2)), cy = jzLerp(H * 0.3, H * 0.7, jzR(d.seed, k, 3)), L = Math.sqrt(W * W + H * H);
        var S = jzShapeLayer(ctx, 'slash', 0, 0), g = jzGrp(S);
