        var tx = jzClamp(ax + sgn * W * jzLerp(0.06, 0.14, jzR(d.seed, k, 1)), W * 0.06, W * 0.94), ty = jzClamp(ay + (k === 0 ? -1 : 1) * H * jzLerp(0.08, 0.16, jzR(d.seed, k, 2)), H * 0.08, H * 0.92);
        var S = jzNoGhost(jzShapeLayer(ctx, 'leader', 0, 0)), g = jzGrp(S);
