        var gd = jzGrp(S); jzAddEllipse(gd, 7, 7, ax, ay); jzAddFill(gd, sc.accent);
        var t = jzText(ctx, labels[k], { font: k === 0 ? 'gothic_med' : 'mono', size: fs, color: sc.fg, x: tx + sgn * W * 0.055, y: ty - fs * 0.9, align: k === 1 ? 'right' : 'left', track: 0.06 });
