        var top = jzR(d.seed, k, 4) < 0.5, x = jzLerp(W * 0.05, W * 0.95, jzR(d.seed, k, 2)), y = top ? jzLerp(H * 0.06, H * 0.24, jzR(d.seed, k, 10)) : jzLerp(H * 0.76, H * 0.94, jzR(d.seed, k, 10));
        var r = jzLerp(H * 0.018, H * 0.06, jzR(d.seed, k, 6)), col = cols[k % 4];
