            for (i = 0; i < 6; i++) { var a = bg3_r(sd, i, 11) * BG3_TAU, d = R * Math.sqrt(bg3_r(sd, i, 12)) * 0.7, cr = R * bg3_rr(0.08, 0.2, sd, i, 13); jzAddEllipse(gc, cr * 2, cr * 2, Math.cos(a) * d, Math.sin(a) * d); }
            jzAddFill(gc, jzMixHex(moonC, sc.bg, 0.22));
