        if (P.phase === 'crescent') bg3_cmask(M, side * R * 0.42, -R * 0.22, R * 0.9, { mode: MaskMode.SUBTRACT });
        jzSetExpr(jzXf(M, 'ADBE Position'), hd + '[' + jzN(mx) + ',my]');
