                var y0 = base - A * 0.25, y1 = base + H * 0.06, MS = bg3_solid(b, sc.bg, 'bg mountains mist ' + (l + 1), W, H);
                bg3_mask(MS, -W, (y0 + y1) / 2, W * 2, H * 3, { f: [0, y1 - y0] });
                jzXf(MS, 'ADBE Opacity').setValue(55);
