        for (k = 0; k <= steps; k++) ls.push(String(((dg - k) % 10 + 10) % 10));
        var Ls = jzText(ctx, ls.join('\r'), { font: font, size: S, color: sc.fg, x: 0, y: 0, align: 'center', track: 0.02, leading: LD, name: 'index digit ' + (i + 1) });
        var dw = jzRect(Ls).width;
