    var gl = jzGrp(Sh, 'rule'); dc1_seg(gl, x0, ry, x0 + w, ry); jzAddStroke(gl, sc.sub, Math.max(1, u), 80); dc1_trim(ctx, gl, '100*oe((time-0.1)/0.5)');
    dc1_op(ctx, Sh, AF, A);
