            dc2_gx(g, 'ADBE Vector Group Opacity', hk + 'var p=cl(1-y/' + jzN(H) + '),fd=Math.pow(Math.sin(Math.PI*p),0.7);fd<=0.05?0:100*(0.2+0.65*fd)');
