        for (k = 0; k < bumps.length; k++) { var dx = x - (x0 + L * bumps[k][0]), R = bumps[k][1] * hc; if (Math.abs(dx) < R) y = Math.min(y, yb - Math.sqrt(R * R - dx * dx)); }
