        for (i = 0; i <= 40; i++) { var an = (300 - 240 * i / 40) * DB1_D; inn.push([Rm * 0.42 + Math.cos(an) * Rm * 0.62 * 1.12, Math.sin(an) * Rm * 0.93]); }
