        for (i = 0; i <= NS; i++) tab.push(db2_pt(db2_part(pts, 0, Math.max(0.0005, i / NS)).slice(-1)[0]));
        var gT = db2_sub(gV, 'bud'), eT = jzAddEllipse(gT, 4.8 * u, 4.8 * u);
