    jzAnimator(L, 'JZ In Decode Dim', [['ADBE Text Fill Color', jzHex(dim)]], q + 'on&&i>fr&&i<=fr+4?100:0');
    jzAnimator(L, 'JZ In Decode Flash', [['ADBE Text Fill Color', jzHex(hi)]], q + 'on&&i<fr&&f-i-1<0.6?100:0');
