    rc.property('ADBE Vector Rect Size').expression = bh + 'var W=' + jzArrExpr(W) + ';[W[fr],' + jzN(m.size * 0.98) + ']';
    rc.property('ADBE Vector Rect Position').expression = bh + 'var X=' + jzArrExpr(g.xs) + ',Y=' + jzArrExpr(g.ys) + ';[X[fr],Y[fr]]';
