    var U0 = vert ? r.top : r.left, U1 = U0 + (vert ? r.height : r.width), A = sz * 0.8, solo = G.nk <= 1;
    for (i = 0; i < G.n; i++) { UU.push(vert ? G.g[i].y : G.g[i].x); SG.push(((solo ? (m.o.mi || 0) : G.g[i].ci) % 2) ? 1 : -1); }
