    var q = eb1_hd(m) + sl + 'var UU=' + eb1_arr(UU) + ',SG=' + eb1_arr(SG) + ',i=textIndex-1,o=cl(((UU[i]||0)-s)/' + jzN(sz * 2.4) + '+0.25),sg=SG[i]||1;';
