            jzSetExpr(rc.property('ADBE Vector Rect Position'), SE + (vert ? '[' + jzN(vc) + ',(a+e)/2]' : '[(a+e)/2,' + jzN(vc) + ']'));
            jzAddFill(g, '#FFFFFF');
