            jzSetExpr(tr.property('ADBE Vector Rect Size'), TE + (vert ? '[' + jzN(th * 0.92) + ',e-t0]' : '[e-t0,' + jzN(th * 0.92) + ']'));
            jzSetExpr(tr.property('ADBE Vector Rect Position'), TE + (vert ? '[' + jzN(vc) + ',(t0+e)/2]' : '[(t0+e)/2,' + jzN(vc) + ']'));
