        if (dyEx) jzSetExpr(tr.property('ADBE Position'), H + 'var I=' + i + ';[' + jzN(bx) + ',' + jzN(by) + '+(' + dyEx + ')]');
        jzSetExpr(tr.property('ADBE Opacity'), H + 'var I=' + i + ';time<OS?0:value*(' + opEx + ')');
