    jzSetExpr(jzGX(g1).property('ADBE Vector Position'), HD + 'var fl=cl(hq/0.16);[' + jzN(Q1[0]) + '+' + jzN(sg * szc * 0.5) + '*fl,' + jzN(Q1[1]) + '-' + xb1_n(szc * 0.6) + '*fl+' + jzN(szc * 1.6) + '*fl*fl]');
