        for (k = 0; k <= 9; k++) { var f = k / 9, hgt = sz * 1.55 * f, w = Math.sin(f * 5 + 7 + i) * sz * 0.09 * f + dir * sz * 0.4 * f; pts.push([w, -hgt]); }
        var sg = jzGrp(S, 'smoke ' + (i + 1)), E = H + xb2_at(m, i, G.N) + UE + 'var ag=(u-0.36)/0.64;';
        jzAddPath(sg, pts, false);
