        var gx = jzGX(sg);             // (fetched after the group's contents are complete)
        gx.property('ADBE Vector Position').setValue([g.cx - F.dn[0] * g.h * 0.4, g.cy - F.dn[1] * g.h * 0.4]);
        gx.property('ADBE Vector Rotation').setValue(-F.deg);
