            ld1_gOp(s1, BH + kb + 'k*100');
            var s2 = ld1_seg(gs, 'string ' + (i + 1) + 'b', BH, kb + 'var X0=mx,Y0=my,X1=ex,Y1=ey', lw);
            ld1_gOp(s2, BH + kb + 'k*100');
