        var pb = 'var B=bal(i),q=B[3]<=0?0:ob(B[3],2.2);x=B[0];y=B[1];r=B[2];sx=sy=0.3+0.7*q;a=B[3]>0?1:0';
        // puffy rim (dark, fat stroke under) + body (the lyric) + gloss dots
