            var Rc = Math.min(W, H) * (n > 5 ? 0.36 : 0.3);
            size = Math.min(ld2_fit(ctx, text, font, Rc * 1.55, Rc * 1.2, tr, lead), u * 0.16);
            var D = jzShapeLayer(ctx, 'disc', cx, cy), g1 = jzGrp(D, 'ring');
