        var faceC = jzP(ctx, 'face', 'light') === 'ink' ? ld2_plateCol(sc, [sc.ink, sc.fg]) : jzMixHex(ld2_light(sc), sc.accent, 0.06);
        var tc = ld2_onCol(sc, faceC), sideC = ld2_shade(sc, faceC, -0.35), pipC = jzMixHex(faceC, tc, 0.7), thick = w * 0.12;
