                jzAddPath(gl, [[Math.cos(a) * rx * r0, Math.sin(a) * ry * r0], [Math.cos(a) * rx * r1, Math.sin(a) * ry * r1]], false); jzAddStroke(gl, sc.sub, Math.max(1.5, u * 0.004));
                var FK = TH + 'var st=Math.floor(time*24);';
